{
  if (fGen == nullptr) {
    if (fOptions.Contains("pndfiltprim"))
    {
      fGen = new PndFilteredPrimaryGenerator();
      //fGen->SetBeam(0, 0, 0, 0);
      //fGen->SetBeamAngle(0, 0, 0, 0);
    }
    else
