  }

  //  if (fTrackIDBranch!="")
  //    {
  //      fTrackID = dynamic_cast<TClonesArray *> (fManager->GetObject(fTrackIDBranch));
  //      if ( ! fTrackID ) {
  //	cout << "-I- PndPidCorrelator::Init: No PndTrackID array! Switching MC propagation OFF" << endl;
  //	fTrackIDBranch = "";
  //      }
  //    }

