PndPidCorrelator::PndPidCorrelator(const char *name, const char *title, Bool_t use_default_setup) : FairTask(name), fUseDefaultDetectorSetup(use_default_setup)
{
  fDebugDir = "./";
  fDebugFile = "./pidcorrelator.root";

  if (fUseDefaultDetectorSetup)
    DefaultDetectorSetup();

  fPidChargedCand = new TClonesArray("PndPidCandidate");

  SetTitle(title);
}

InitStatus PndPidCorrelator::Init()
{
  if (fTrackingSystemInfo == nullptr && fCalorimeterInfo == nullptr) {
    LOG(error) << "PndPidCorrelator(" << GetName() << ")::Init(): Neither tracking nor calorimeter info set, abort!";
    return kFATAL;
  }
  if (fIdealHyp && fTrackingSystemInfo != nullptr) {
    if (!fTrackingSystemInfo->SetMcTrack(fManager)) {
      return kERROR;
    }
  } else {
    fPidHyp = FindPidHyp(fPidHyp);
  }

  if (fIdeal) {
    LOG_IF(info, fVerbose > 0) << "PndPidCorrelator::Init: Using MonteCarlo correlation";
  }

  Register();

  fCorrPar->printParams();

  if (fUsePropagator) {
    SetPropagator(fPropagator);
    if (fTrackingSystemInfo != nullptr) {
      fTrackingSystemInfo->SetPropagator(fPropagator);
    }
  }

  if (fDebugMode) {
    fFileDebugNtuples = TFile::Open(fDebugDir + fDebugFile, "RECREATE");
    LOG_IF(info, fVerbose > 8) << "PndPidCorrelator::Init: Filling Debug histograms";
  }

  SetupDetectorParams();
  if (fTrackingSystemInfo != nullptr) {
    if (!fTrackingSystemInfo->Setup(fManager, fPropagator, &fDetectorParams)) {
      return kFATAL;
    }
  } else {
    LOG_IF(info, fVerbose > 0) << "PndPidCorrelator::Init(): No tracking information -> create only neutral candidates";
  }

  if (fCalorimeterInfo != nullptr) {
    if (!fCalorimeterInfo->Setup(fManager, fPropagator, &fDetectorParams)) {
      return kFATAL;
    }
  } else {
    LOG_IF(info, fVerbose > 0) << "PndPidCorrelator::Init(): No calorimeter information -> create only charged candidates";
  }

  for (Int_t i = fBarrelDetectors.size() - 1; i >= 0; i--) {
    if (fBarrelDetectors.at(i) == nullptr) {
      LOG(warn) << "PndPidCorrelator::Init: Barrel detector " << i << " is not set!";
      LOG_IF(info, fVerbose > 5) << "Removing it from fBarrelDetectors.";
      fBarrelDetectors.erase(fBarrelDetectors.begin() + i);
      continue;
    }
    if (!(fBarrelDetectors.at(i))->Setup(fManager, fPropagator, &fDetectorParams)) {
      return kFATAL;
    }
  }
  for (Int_t i = fForwardDetectors.size() - 1; i >= 0; i--) {
    if (fForwardDetectors.at(i) == nullptr) {
      LOG(warn) << "PndPidCorrelator::Init: Forward detector " << i << " is not set!";
      LOG_IF(info, fVerbose > 5) << "Removing it from fForwardDetectors.";
      fForwardDetectors.erase(fForwardDetectors.begin() + i);
      continue;
    }
    if (!(fForwardDetectors.at(i))->Setup(fManager, fPropagator, &fDetectorParams)) {
      return kFATAL;
    }
  }

  if (fFast) {
    LOG_IF(info, fVerbose > 0) << "PndPidCorrelator::Init: Using fast correlator!!";
  }

  LOG_IF(info, fVerbose > 5) << "PndPidCorrelator::Init: Success!";
  fEventCounter = 0;
  return kSUCCESS;
}

InitStatus PndPidCorrelator::Init() {

  //  cout << "InitStatus PndPidCorrelator::Init()" << endl;

  FairRootManager *fManager =FairRootManager::Instance();

  if (fUseFittedVertex && !fEventVertexFileName.IsNull()) {
    TDirectory* savedDirectory = gDirectory;
    fEventVertexFile = TFile::Open(fEventVertexFileName, "READ");
    if (savedDirectory) savedDirectory->cd();
    if (!fEventVertexFile || fEventVertexFile->IsZombie()) {
      cout << "-E- PndPidCorrelator::Init: Cannot open event POCA file "
           << fEventVertexFileName << endl;
      return kERROR;
    }
    fEventVertexTree = dynamic_cast<TTree*>(fEventVertexFile->Get("event_poca"));
    if (!fEventVertexTree) {
      cout << "-E- PndPidCorrelator::Init: Tree 'event_poca' is missing in "
           << fEventVertexFileName << endl;
      return kERROR;
    }
    fEventVertexTree->SetBranchAddress("event_id", &fEventVertexId);
    fEventVertexTree->SetBranchAddress("x", &fEventVertexX);
    fEventVertexTree->SetBranchAddress("y", &fEventVertexY);
    fEventVertexTree->SetBranchAddress("z", &fEventVertexZ);
    fEventVertexTree->SetBranchAddress("valid", &fEventVertexValid);
    cout << "-I- PndPidCorrelator::Init: Using event-level POCA vertices from "
         << fEventVertexFileName << endl;
  }

  fTrack = dynamic_cast<TClonesArray *> (fManager->GetObject(fTrackBranch));
  if ( ! fTrack ) {
    cout << "-I- PndPidCorrelator::Init: No PndTrack array!" << endl;
    return kERROR;
  }

  // Get the MCTrack array
  fMcTrackPro = dynamic_cast<TClonesArray *> (fManager->GetObject("MCTrack"));
  if (!fMcTrackPro) {
      cout << "MCTrack branch not found, cannot use MC truth for propagation!" << endl;
      fUseMcTruthForTarget = kFALSE; // Force the flag to false if data is not available
  }

  //  if (fTrackIDBranch!="")
  //    {
  //      fTrackID = dynamic_cast<TClonesArray *> (fManager->GetObject(fTrackIDBranch));
  //      if ( ! fTrackID ) {
  //	cout << "-I- PndPidCorrelator::Init: No PndTrackID array! Switching MC propagation OFF" << endl;
  //	fTrackIDBranch = "";
  //      }
  //    }

  if (fTrackBranch2!="")
  {
    fTrack2 = dynamic_cast<TClonesArray *> (fManager->GetObject(fTrackBranch2));
    if ( ! fTrack2 ) {
      cout << "-I- PndPidCorrelator::Init: No 2nd PndTrack array!" << endl;
      return kERROR;
    }
  }

  //  if (fTrackIDBranch2!="")
  //    {
  //      fTrackID2 = dynamic_cast<TClonesArray *> (fManager->GetObject(fTrackIDBranch2));
  //      if ( ! fTrackID2 ) {
  //	cout << "-I- PndPidCorrelator::Init: No 2nd PndTrackID array! Switching MC propagation OFF" << endl;
  //	fTrackIDBranch2 = "";
  //      }
  //    }

  // *** STT ***
  if (fSttMode)
  {
    if (fMixMode==kFALSE)
    {
      fSttHit = dynamic_cast<TClonesArray *> ( fManager->GetObject("STTHit"));
      if ( fSttHit )
      {
        cout << "-I- PndPidCorrelator::Init: Using STTHit" << endl;
        fSttMode = 2;
      }
      else
      {
        cout << "-W- PndPidCorrelator::Init: No STT hits array! Switching STT OFF" << endl;
        fSttMode = 0;
      }
    }
    else
    {
      fSttHit = dynamic_cast<TClonesArray *> (fManager->GetObject("STTHitMix"));
      if ( fSttHit )
      {
        cout << "-I- PndPidCorrelator::Init: Using STTHitMix" << endl;
        fSttMode = 2;
      }
      else
      {
        cout << "-W- PndPidCorrelator::Init: No STT hits mix array! Switching STT OFF" << endl;
        fSttMode = 0;
      }
    }
  }

