void runLmdFit(string input_file_dir, string fit_config_path,
               string acceptance_file_dir, string reference_acceptance_file_dir,
               unsigned int nthreads, string lumiFitResultPath,
               string recoIPfile) {

  boost::chrono::thread_clock::time_point start =
      boost::chrono::thread_clock::now();

  PndLmdRuntimeConfiguration &lmd_runtime_config =
      PndLmdRuntimeConfiguration::Instance();
  lmd_runtime_config.setNumberOfThreads(nthreads);
  lmd_runtime_config.setGeneralConfigDirectory(fit_config_path);

  // TODO: why is the file name hard coded?
  lmd_runtime_config.readAcceptanceOffsetTransformationParameters(
      "offset_trafo_matrix.json");

  lmd_runtime_config.setElasticDataInputDirectory(input_file_dir);
  lmd_runtime_config.setAcceptanceResolutionInputDirectory(acceptance_file_dir);
  lmd_runtime_config.setReferenceAcceptanceResolutionInputDirectory(
      reference_acceptance_file_dir);

  lmd_runtime_config.setElasticDataName("lmd_data_.*of.*.root");
  lmd_runtime_config.setAccDataName("lmd_acc_data_.*of1.root");
  lmd_runtime_config.setResDataName("lmd_res_data_.*of1.root");
  lmd_runtime_config.setVertexDataName("lmd_vertex_data_.*of1.root");

  // ============================== read data ============================== //

  // get lmd data and objects from files
  PndLmdDataFacade lmd_data_facade;

  PndLmdFitFacade lmd_fit_facade;

  // get vertex data and determine and run ip determination for these
  vector<PndLmdHistogramData> my_vertex_vec = lmd_data_facade.getVertexData();
  // do fits

  // TODO: why is the file name hard coded?
  lmd_runtime_config.readFitConfig("vertex_fitconfig.json");
  lmd_fit_facade.fitVertexData(my_vertex_vec);

  // read reco IP from file
  std::pair<double, double> ip_offsets(0.0, 0.0);
  if (recoIPfile == "") {
    std::cout << "WARNING: no reco IP file given, using 0,0 as reco IP\n";
  } else {
    std::cout << "reading reco IP from file: " << recoIPfile << "\n";
    boost::property_tree::ptree reco_ip_ptree;
    read_json(recoIPfile, reco_ip_ptree);
    double reco_ip_x = reco_ip_ptree.get<double>("ip_x");
    double reco_ip_y = reco_ip_ptree.get<double>("ip_y");
    ip_offsets.first = reco_ip_x;
    ip_offsets.second = reco_ip_y;
  }
  // print them just to be sure
  std::cout << "Read reco IP values " << ip_offsets.first << " and "
            << ip_offsets.second << "\n";

  // ok now we have to set the correct ip offsets to the elastic data sets
  // so compare the data on an abstract level
  vector<PndLmdAngularData> all_lmd_data_vec = lmd_data_facade.getElasticData();
  for (auto &data : all_lmd_data_vec) {
    data.setIPOffsets(ip_offsets);
  }

  lmd_runtime_config.readFitConfig(fit_config_path);

  // filter out specific data
  LumiFit::LmdDimensionOptions lmd_dim_opt;
  lmd_dim_opt.dimension_type = LumiFit::THETA_X;
  lmd_dim_opt.track_type = LumiFit::MC;

  const boost::property_tree::ptree &fit_config_ptree =
      lmd_runtime_config.getFitConfigTree();
  if (fit_config_ptree.get<bool>(
          "fit.fit_model_options.acceptance_correction_active") == true) {
    lmd_dim_opt.track_type = LumiFit::MC_ACC;
    if (fit_config_ptree.get<bool>(
            "fit.fit_model_options.resolution_smearing_active") == true)
      lmd_dim_opt.track_type = LumiFit::RECO;
  }

  LumiFit::Comparisons::DataPrimaryDimensionOptionsFilter filter(lmd_dim_opt);
  vector<PndLmdAngularData> my_lmd_data_vec =
      lmd_data_facade.filterData<PndLmdAngularData>(all_lmd_data_vec, filter);

  LumiFit::Comparisons::NoSecondaryTrackFilter no_cut_on_secondary_filter;
  my_lmd_data_vec = lmd_data_facade.filterData<PndLmdAngularData>(
      my_lmd_data_vec, no_cut_on_secondary_filter);

hist_bunch createHistogramsFromRawDPMData(data_options &data_opt,
                                          unsigned int num_events) {
  hist_bunch return_histgrams;

  std::pair<TTree *, double> events = PbarPElasticScattering::generateEvents(
      data_opt.momentum, num_events, data_opt.theta_bound_low_in_mrad,
      data_opt.theta_bound_high_in_mrad, data_opt.phi_bound_low,
      data_opt.phi_bound_high, 1234);

  data_opt.elastic_cross_section = events.second;

  TClonesArray *fEvt = new TClonesArray("TParticle", 100);
  TTree &tree(*events.first);
  tree.SetBranchAddress("Particles", &fEvt);

  std::cout << "tree has " << tree.GetEntries() << " entries" << std::endl;
  unsigned int num_events_to_process = tree.GetEntries();
  if (num_events != -1 && num_events < num_events_to_process)
    num_events_to_process = num_events;

  PndLmdModelFactory model_factory;
  double t_bound_low = model_factory.getMomentumTransferFromTheta(
      data_opt.momentum, data_opt.theta_bound_low_in_mrad / 1000.0);
  double t_bound_high = model_factory.getMomentumTransferFromTheta(
      data_opt.momentum, data_opt.theta_bound_high_in_mrad / 1000.0);

  // create histograms from raw dpm files
  return_histgrams.th_hist =
      new TH1D("hist_dpm_theta", "", data_opt.theta_binning,
               data_opt.theta_bound_low_in_mrad / 1000.0,
               data_opt.theta_bound_high_in_mrad / 1000.0);
  return_histgrams.t_hist = new TH1D("hist_dpm_t", "", data_opt.theta_binning,
                                     t_bound_low, t_bound_high);
  return_histgrams.th_phi_hist =
      new TH2D("hist_dpm_theta_phi", "", data_opt.theta_binning,
               data_opt.theta_bound_low_in_mrad / 1000.0,
               data_opt.theta_bound_high_in_mrad / 1000.0, data_opt.phi_binning,
               data_opt.phi_bound_low, data_opt.phi_bound_high);

  std::cout << "Processing " << num_events_to_process << " events!"
            << std::endl;

  return_histgrams.gen_lumi =
      num_events_to_process / data_opt.elastic_cross_section;

  TDatabasePDG *pdg = TDatabasePDG::Instance();
  TLorentzVector ingoing(
      0, 0, data_opt.momentum,
      TMath::Sqrt(TMath::Power(data_opt.momentum, 2.0) +
                  TMath::Power(pdg->GetParticle(-2212)->Mass(), 2.0)));

  TVector3 tilt(tan(data_opt.tilt_x), tan(data_opt.tilt_y), 1.0);
  TVector3 zprime = tilt.Unit();
  TVector3 yprime(-zprime.Y(), zprime.X(), 0.0);
  TVector3 xprime = yprime.Cross(zprime);
  double beta = acos(zprime.Z());
  double alpha = atan2(zprime.X(), -zprime.Y());
  double gamma = atan2(xprime.Z(), yprime.Z());

  for (unsigned int i = 0; i < num_events_to_process; i++) {
    tree.GetEntry(i);
    for (unsigned int np = 0; np < fEvt->GetEntries(); np++) {
      TParticle *particle = (TParticle *)fEvt->At(np);
      if (particle->GetPdgCode() == -2212) {
        TLorentzVector outgoing;
        particle->Momentum(outgoing);
        TVector3 measured_direction(outgoing.Vect());

        // rotating it myself
        if (false) {
          measured_direction.RotateZ(alpha);
          measured_direction.Rotate(beta, yprime);
          measured_direction.Rotate(gamma, zprime);
        }
        // if data should be rotated like in pandaroot
        // if (true)
        //  measured_direction.RotateUz(zprime);

        return_histgrams.t_hist->Fill(-1.0 * (outgoing - ingoing).M2());
        return_histgrams.th_hist->Fill(measured_direction.Theta());
        return_histgrams.th_phi_hist->Fill(measured_direction.Theta(),
                                           measured_direction.Phi());
      }
    }
  }
  return return_histgrams;
}

bool PndLmdFitOptions::lessThanModelOptionsProperyTree(
    const std::map<std::string, std::string> &lhs,
    const std::map<std::string, std::string> &rhs) const {
  if (lhs < rhs)
    return true;
  else if (lhs > rhs) {
    return false;
  }
  return false;
}

PndLmdFitDataBundle PndLmdFitFacade::doLuminosityFits(
    std::vector<PndLmdAngularData> &lmd_data_vec) {
  PndLmdDataFacade lmd_data_facade;
  PndLmdFitDataBundle data_bundle;

  std::vector<PndLmdAcceptance> matching_acc;

  cout << "Running LumiFit on " << lmd_data_vec.size()
       << " angular data sets...." << endl;

  for (auto &lmd_data : lmd_data_vec) {
    cout << "Data dimensions: "
         << lmd_data.getPrimaryDimension().createDimensionLabel();
    if (lmd_data.getSecondaryDimension().is_active)
      cout << " vs. "
           << lmd_data.getSecondaryDimension().createDimensionLabel();
    cout << "\n";

    PndLmdFitOptions fit_options(createFitOptions(lmd_data));

    if (fit_options.getModelOptionsPropertyTree().get<bool>(
            "resolution_smearing_active")) {
      // matching_res = lmd_data_facade.getMatchingResolutions(resolution_pool,
      //    lmd_data_vec[elastic_data_index]);
      // model_factory.setResolutions(matching_res);
      if (resolution_map_pool.size() > 0) {
        if (resolution_map_pool.begin()->getHitMap().size() == 0) {
          std::cout << "Requesting fit with resolution smearing, however "
                       "resolution map data is empty!"
                    << "Hence skipping this fit!\n";
          continue;
        }
        model_factory.setResolutionMapData(*resolution_map_pool.begin());
      } else {
        std::cout << "Requesting fit with resolution smearing, however no "
                     "resolution map data was specified!"
                  << "Hence skipping this fit!\n";
        continue;
      }
    }

    if (fit_options.getModelOptionsPropertyTree().get<bool>(
            "acceptance_correction_active")) {
      matching_acc =
          lmd_data_facade.getMatchingAcceptances(acceptance_pool, lmd_data);

      for (auto const &acc : matching_acc) {
        // set acc in factory
        model_factory.setAcceptance(acc);

        fitElasticPPbar(lmd_data);

        data_bundle.addFittedElasticData(lmd_data);
        data_bundle.attachAcceptanceToCurrentData(
            model_factory.getAcceptance());
        if (fit_options.getModelOptionsPropertyTree().get<bool>(
                "resolution_smearing_active"))
          data_bundle.attachResolutionMapDataToCurrentData(
              *resolution_map_pool.begin());
      }
    } else {
      fitElasticPPbar(lmd_data);

      data_bundle.addFittedElasticData(lmd_data);
    }
    data_bundle.addCurrentDataBundleToList();
  }

  return data_bundle;
}

std::vector<T> getDataFromFile(TFile &f,
                                 std::string overwriteFilename) const {
    std::vector<T> lmd_data_vec;

    unsigned int counter = 0;

    TIter next(f.GetListOfKeys());
    TKey *key;
    while ((key = (TKey *)next())) {

      T *data;
      f.GetObject(key->GetName(), data);
      if (data) {
        counter++;
        lmd_data_vec.push_back(*data);
        delete data; // this delete is crucial! otherwise we have a memory leak!
      }
    }
    // std::cout << "Found " << counter << " objects!" << std::endl;
    return lmd_data_vec;
  }

