PndApolloniusTripletTrackFinderTask::PndApolloniusTripletTrackFinderTask()
  : FairTask("ApolloniusTripletTrackFinderTask"), fWithTubeReduction(false), fWithCombiReduction(false), fSTT("STTHit")
{
}

// -----   Destructor   ----------------------------------------------------
