  : fRlimit(rlimit), fRsigma(rsigma), fDrDz(drdz), fDmin(0.), fDmax(0.), fVerbose(0), fDoExtended(false), fDensityFile(densityFile), fDensityGraph(nullptr), fInvertedCDF(nullptr)
{
  // Constructor.
}

