PndSttSkewStrawPzFinderTask::PndSttSkewStrawPzFinderTask() : fStoredata(false), fWithRiemann(false), fMethod(1), fStepTheta(90), fStepR(50), OutputPrefix("")
{
  FairRuntimeDb *rtdb = FairRunAna::Instance()->GetRuntimeDb();
