Bool_t PndPidCorrelator::GetTrackInfo(PndTrack* track, PndPidCandidate* pidCand)
{
  Int_t charge =   TMath::Sign(1, track->GetParamFirst().GetQ());
  pidCand->SetCharge(charge);

  TVector3 first(track->GetParamFirst().GetX(),
                 track->GetParamFirst().GetY(),
                 track->GetParamFirst().GetZ());
  TVector3 last(track->GetParamLast().GetX(),
                track->GetParamLast().GetY(),
                track->GetParamLast().GetZ());
  FairTrackParP par = track->GetParamFirst();
  Int_t ierr = 0;
  FairTrackParH *fRes;
  TVector3 momentum, startpos;

  if (fGeanePro && fBackPropagate) // Overwrites vertex if Geane is used and if backpropagation
    {
    //FairTrackParH *helix = new FairTrackParH(&par, ierr);
    fRes= new FairTrackParH();

    // track back to Origin
    // [ralfk: changed to propagate to z axis - 03/2011]
    // fGeanePropagator->SetPoint(TVector3(0.,0.,10.));
    // fGeanePropagator->PropagateToPCA(1, -1);
    // std::cout << "PndPidCorrelator::GetTrackInfo :: Back propagation to IP: 0, 0, 10" << std::endl;
    // Propagatetrack back to z Axis
    // fGeanePropagator->PropagateToPCA(2, -1);// track back to z axis
    // TVector3 ex1(0.,0.,-50.); // virtual wire, dimensions chosen arbitrarily
    // TVector3 ex2(0.,0.,100.); // we expect fast decaying tracks to be close to that
    // fGeanePropagator->SetWire(ex1,ex2);

    // --- Propagation Target Logic ---
    TVector3 targetPoint;
    bool targetSet = false;
    bool useFittedVertexAxis = false; // Flag to indicate if we should use axis propagation

    // 1. Prefer the event-level POCA loaded by Exec(). The environment
    // variables remain as a backwards-compatible fallback for fixed-IP jobs.
    if (fUseFittedVertex) {
      if (fEventVertexTree) {
        if (!fEventVertexValid || !std::isfinite(fEventVertexX) ||
            !std::isfinite(fEventVertexY) || !std::isfinite(fEventVertexZ)) {
          std::cout << "-W- PndPidTrackInfo::GetIP: No valid POCA for event "
                    << (fEventCounter - 1) << "; skipping this track." << std::endl;
          return kFALSE;
        }
        targetPoint.SetXYZ(fEventVertexX, fEventVertexY, fEventVertexZ);
        targetSet = true;
        useFittedVertexAxis = true;
      }

      if (!targetSet) {
        const char* vtx_x_str = std::getenv("FIT_VERTEX_X");
        const char* vtx_y_str = std::getenv("FIT_VERTEX_Y");
        const char* vtx_z_str = std::getenv("FIT_VERTEX_Z");

        if (vtx_x_str && vtx_y_str && vtx_z_str) {
            try {
                double x = std::stod(vtx_x_str);
                double y = std::stod(vtx_y_str);
                double z = std::stod(vtx_z_str);
                targetPoint.SetXYZ(x, y, z);
                targetSet = true;
                useFittedVertexAxis = true; // Enable axis propagation for fitted vertex
                std::cout << "-I- PndPidTrackInfo::GetIP: Using fitted vertex from environment. Will propagate to axis through: ("
                          << targetPoint.X() << ", " << targetPoint.Y() << ")" << std::endl;
            } catch (const std::invalid_argument& e) {
                std::cerr << "-W- PndPidTrackInfo::GetIP: Invalid argument when converting fitted vertex from environment. " << e.what() << std::endl;
            } catch (const std::out_of_range& e) {
                std::cerr << "-W- PndPidTrackInfo::GetIP: Out of range when converting fitted vertex from environment. " << e.what() << std::endl;
            }
        } else {
            std::cout << "-W- PndPidTrackInfo::GetIP: fUseFittedVertex is true, but one or more FIT_VERTEX environment variables are not set." << std::endl;
        }
      }
    }

